-- Trusted onboarding columns can only change through narrowly-scoped SECURITY DEFINER RPCs.
create or replace function public.guard_onboarding_state() returns trigger language plpgsql security definer set search_path=public as $$ begin if (new.onboarding_completed,new.recovery_acknowledged_at,new.profile_completed_at,new.country_handled_at,new.interests_handled_at) is distinct from (old.onboarding_completed,old.recovery_acknowledged_at,old.profile_completed_at,old.country_handled_at,old.interests_handled_at) and current_setting('app.onboarding_rpc',true) is distinct from '1' then raise exception 'Trusted onboarding state must be updated by an onboarding operation'; end if; return new; end $$;
drop trigger if exists guard_onboarding_state_trigger on public.profiles; create trigger guard_onboarding_state_trigger before update on public.profiles for each row execute procedure public.guard_onboarding_state();
create or replace function public.acknowledge_recovery() returns void language plpgsql security definer set search_path=public as $$ begin perform require_authenticated(); perform set_config('app.onboarding_rpc','1',true); update profiles set recovery_acknowledged_at=coalesce(recovery_acknowledged_at,now()) where id=auth.uid(); end $$;
create or replace function public.complete_onboarding() returns boolean language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); country text; begin perform require_authenticated(); perform set_config('app.onboarding_rpc','1',true); select country_code into country from profiles where id=uid and recovery_acknowledged_at is not null and profile_completed_at is not null and country_handled_at is not null and interests_handled_at is not null; if not found then raise exception 'Onboarding steps are incomplete'; end if; if not exists(select 1 from room_members m join rooms r on r.id=m.room_id where m.user_id=uid and r.kind='world') then raise exception 'World membership is required'; end if; update profiles set onboarding_completed=true where id=uid; return true; end $$;
revoke all on function public.acknowledge_recovery() from public; grant execute on function public.acknowledge_recovery() to authenticated;
